def num(x):
    return f"{x:.0f}" if abs(x - round(x)) < 1e-9 else f"{x:.1f}"


def rule(p):
    if not p["answered"]:
        return "0/0"
    lo, hi = p["ci"]
    return f"{num(p['correct'])}/{p['answered']} = {100 * p['precision']:.1f}% [{100 * lo:.1f}, {100 * hi:.1f}]"


def diff(d):
    if d.get("diff") is None or d["ci"][0] is None:
        return "n/a"
    return f"{100 * d['diff']:+.1f} [{100 * d['ci'][0]:+.1f}, {100 * d['ci'][1]:+.1f}]" + ("" if d["separates"] else " ns")


def rate(k, n, lo, hi):
    if not n:
        return "none"
    return f"{100 * k / n:.1f}% [{100 * lo:.1f}, {100 * hi:.1f}] of {n}"


def b_txt(c):
    return f"{c['b_fail']} (n/a)" if c["b_fail_rate"] is None else f"{c['b_fail']} ({100 * c['b_fail_rate']:.1f}%)"


def table(head, rows):
    out = ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)]
    for r in rows:
        out.append("| " + " | ".join(str(x) for x in r) + " |")
    return "\n".join(out)


